import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

// 준비 값: 보낼 조각 수, 송신 창 크기, 처음 보낼 때 사라지는 조각 번호예요.
static final int SEGMENTS = 6;
static final int WINDOW = 3;
static final String LOST = "2";

// 송신자 상태: base는 아직 확인받지 못한 가장 앞 조각, next는 다음에 새로 보낼 조각이에요.
static int base = 0;
static int next = 0;
static int resent = 0;
// 수신자 상태: 기다리는 번호와 앱에 전달한 순서예요.
static int expected = 0;
static final List<Integer> delivered = new ArrayList<>();
static final Set<Integer> lostOnce = new TreeSet<>();

// 준비 코드: 수신자는 순서대로 온 조각만 앱에 전달해요.
// 돌려주는 확인 번호(ACK)는 "여기까지 빠짐없이 받았다"는 마지막 번호예요.
static int receive(int seq) {
    if (seq == expected) {
        delivered.add(seq);
        expected++;
        System.out.println("수신 " + seq + " | 전달 " + delivered);
    } else {
        System.out.println("수신 " + seq + " | 버림 기다리는 번호 " + expected);
    }
    return expected - 1;
}

// 확인 번호 ack를 받았을 때 송신 창의 앞(base)을 옮겨요.
static void onAck(int ack) {
    // 고칠 곳: 지금은 확인을 하나 받을 때마다 창을 한 칸씩 옮겨요.
    base = base + 1;
    System.out.println("확인 " + ack + " | 창 " + base + "~" + (base + WINDOW - 1));
}

void main() {
    for (String n : LOST.split(",")) {
        if (!n.isBlank()) lostOnce.add(Integer.parseInt(n.trim()));
    }
    int round = 0;
    while (base < SEGMENTS && round < 20) {
        round++;
        int before = base;
        List<Integer> acks = new ArrayList<>();
        // 준비 코드: 창 안에서 아직 안 보낸 조각을 보내요.
        while (next < base + WINDOW && next < SEGMENTS) {
            if (lostOnce.remove(next)) {
                System.out.println("보냄 " + next + " | 유실");
            } else {
                System.out.println("보냄 " + next + " | 도착");
                acks.add(receive(next));
            }
            next++;
        }
        for (int ack : acks) onAck(ack);
        // 준비 코드: 이번 차례에 창이 앞으로 가지 않았으면 시간 초과예요. base부터 다시 보내요.
        if (base == before && base < SEGMENTS) {
            resent += next - base;
            System.out.println("시간 초과 | 다시 보냄 " + base + "~" + (next - 1));
            next = base;
        }
    }
    System.out.println(base >= SEGMENTS ? "송신자: 모두 확인받았어요." : "송신자: 확인받지 못한 조각이 남았어요.");
    System.out.println("수신자 전달 순서 " + delivered + ", 다시 보낸 조각 " + resent + "개");
}

